const CloudantV1 = global.get("CloudantV1");
const database = env.get("CLOUDANT_DATABASE");
const cloudantUrl = env.get("CLOUDANT_URL");
const cloudantApiKey = env.get("CLOUDANT_APIKEY");

if (!CloudantV1 || !cloudantUrl || !cloudantApiKey || !database) {
    msg.statusCode = 503;
    msg.payload = { error: "Cloudant is not configured" };
    return msg;
}

CloudantV1.newInstance({}).getDatabaseInformation({ db: database })
    .then(({ result }) => {
        msg.statusCode = 200;
        msg.payload = { status: "ok", database: result.db_name };
        node.send(msg);
        node.done();
    })
    .catch((error) => {
        node.error(error.message, msg);
        msg.statusCode = Number.isInteger(error.status) ? error.status : 502;
        msg.payload = { error: "Cloudant request failed" };
        node.send(msg);
        node.done();
    });
return;

const CloudantV1 = global.get("CloudantV1");
const database = env.get("CLOUDANT_DATABASE");
const cloudantUrl = env.get("CLOUDANT_URL");
const cloudantApiKey = env.get("CLOUDANT_APIKEY");

if (!msg.payload || Array.isArray(msg.payload) || typeof msg.payload !== "object") {
    msg.statusCode = 400;
    msg.payload = { error: "A JSON object is required" };
    node.send([null, msg]);
    node.done();
    return;
}

if (!CloudantV1 || !cloudantUrl || !cloudantApiKey || !database) {
    msg.statusCode = 503;
    msg.payload = { error: "Cloudant is not configured" };
    node.send([null, msg]);
    node.done();
    return;
}

CloudantV1.newInstance({}).postDocument({ db: database, document: msg.payload })
    .then(({ result, status }) => {
        msg.statusCode = status || 201;
        msg.payload = result;
        node.send([msg, null]);
        node.done();
    })
    .catch((error) => {
        node.error(error.message, msg);
        msg.statusCode = Number.isInteger(error.status) ? error.status : 502;
        msg.payload = { error: "Cloudant request failed" };
        node.send([null, msg]);
        node.done();
    });
return;
